from pathlib import Path
import json,textwrap
R=Path(__file__).resolve().parents[1];S=R/'site';S.mkdir(exist_ok=True)
results=[]
for profile,suite in [('optimistic','happy-only'),('optimistic','complete'),('guarded','happy-only'),('guarded','complete')]:
 d=json.loads((R/f'reports/reference/{profile}-{suite}/report.json').read_text(encoding='utf-8'));results.append(d)
data=json.dumps(results).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
html=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ASTERION — Rehearsal Evidence Explorer</title>
<style>
:root{--bg:#080f1c;--panel:#101c2c;--panel2:#15243a;--edge:#293d55;--ink:#eff4f9;--muted:#9cacc2;--mint:#77e6c3;--amber:#f4cd89;--red:#ff9bab;--purple:#b9adff}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:15px/1.55 system-ui,-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;color:var(--ink)}a{color:var(--mint);text-decoration:none}button{font:inherit;cursor:pointer}header{height:88px;border-bottom:1px solid var(--edge);display:flex;align-items:center;justify-content:space-between;padding:0 5%;background:#0c1624}.brand{display:flex;align-items:center;gap:14px;font-size:22px;font-weight:750;letter-spacing:4px}.brand svg{width:34px;height:34px}.nav{display:flex;gap:28px;font-size:13px;color:var(--muted)}main{max-width:1450px;margin:auto;padding:44px 40px 68px}.kicker{color:var(--mint);letter-spacing:2.8px;text-transform:uppercase;font-size:11px;font-weight:650}.top{display:grid;grid-template-columns:1fr 380px;gap:48px;align-items:center}h1{font-size:48px;line-height:1.08;letter-spacing:-1.7px;margin:12px 0 20px;max-width:800px}h2{font-size:22px;letter-spacing:-.5px;margin:0 0 12px}h3{margin:0 0 12px;font-size:18px}.lead{color:var(--muted);max-width:780px;font-size:16px;margin:0}.scope{border:1px solid var(--edge);border-radius:14px;padding:24px;background:var(--panel);font-size:13px}.scope b{display:block;color:var(--amber);margin-bottom:8px}.scope p{color:var(--muted);margin:0}.controls{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:34px 0 22px}.tab{border:1px solid var(--edge);border-radius:10px;padding:17px;text-align:left;background:var(--panel);color:var(--ink)}.tab small{display:block;color:var(--muted);font-size:12px;margin-top:4px}.tab.active{border-color:var(--mint);box-shadow:inset 0 3px 0 var(--mint);background:#102821}.stats{display:grid;grid-template-columns:1.2fr 1fr 1fr 1fr;gap:16px}.stat{border:1px solid var(--edge);border-radius:14px;padding:22px;background:var(--panel)}.label{font-size:10px;letter-spacing:1.7px;color:var(--muted);text-transform:uppercase}.big{font-size:33px;font-weight:720;line-height:1.3;margin-top:9px;letter-spacing:-.8px}.detail{color:var(--muted);font-size:12px;margin-top:8px}.mint{color:var(--mint)}.amber{color:var(--amber)}.red{color:var(--red)}.status{font-size:25px}.bar{height:5px;background:var(--edge);border-radius:8px;margin-top:13px;overflow:hidden}.fill{height:100%;background:var(--mint)}.workspace{display:grid;grid-template-columns:1.5fr 1fr;gap:22px;margin-top:26px}.panel{background:var(--panel);border:1px solid var(--edge);border-radius:15px;padding:25px}.panel-head{display:flex;justify-content:space-between;gap:15px;align-items:start}.chip{font-size:10px;padding:5px 9px;border:1px solid var(--edge);border-radius:20px;color:var(--muted);white-space:nowrap}.muted{color:var(--muted)}table{width:100%;border-collapse:collapse;margin-top:18px;font-size:12px}th{text-align:left;color:var(--muted);font-size:10px;letter-spacing:1.4px;font-weight:600}td,th{padding:10px 7px;border-bottom:1px solid #24344a}td:first-child{font-weight:600}.pill{display:inline-block;min-width:58px;text-align:center;border-radius:5px;padding:3px 7px;font-size:10px;font-weight:700;letter-spacing:.5px}.PASS{background:#133d32;color:var(--mint)}.FAIL{background:#452636;color:var(--red)}.MISSING{background:#3d3428;color:var(--amber)}select{width:100%;background:#0c1624;color:var(--ink);border:1px solid var(--edge);border-radius:8px;padding:12px;font-size:13px;margin:12px 0}pre{font:12px/1.6 ui-monospace,SFMono-Regular,Consolas,monospace;background:#091321;border:1px solid var(--edge);border-radius:10px;padding:18px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;max-height:460px}.empty{padding:30px 20px;background:#0c1624;border:1px dashed var(--edge);border-radius:10px;color:var(--muted);font-size:14px}.sub{margin-top:24px;padding-top:18px;border-top:1px solid var(--edge)}.note{font-size:12px;color:var(--muted);margin-top:14px}.digest{font:11px/1.6 ui-monospace,monospace;word-break:break-all;color:var(--purple)}.atlas{display:flex;flex-wrap:wrap;gap:12px;margin-top:20px}.atlas a{padding:10px 14px;border:1px solid var(--edge);border-radius:8px;font-size:12px}.footer{display:flex;justify-content:space-between;border-top:1px solid var(--edge);padding-top:24px;margin-top:34px;color:var(--muted);font-size:12px}.caption{font-size:12px;color:var(--muted);margin:10px 0 0}.method{border-left:3px solid var(--amber);padding:11px 16px;margin-top:20px;background:#191e27;font-size:13px;color:var(--muted)}
@media(max-width:1000px){.top,.workspace{grid-template-columns:1fr}.top{gap:24px}.scope{padding:18px}.stats,.controls{grid-template-columns:repeat(2,1fr)}h1{font-size:39px}.nav{display:none}}@media(max-width:550px){main{padding:25px 16px}.controls,.stats{grid-template-columns:1fr 1fr}.stat{padding:16px}.big{font-size:25px}.status{font-size:19px}h1{font-size:35px}.panel{padding:16px}td,th{padding:8px 4px;font-size:10px}.footer{display:block}}
</style></head><body><header><div class="brand"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M3 35V5H35V31H10V12H27V23H18" fill="none" stroke="#77e6c3" stroke-width="3"/></svg>ASTERION</div><nav class="nav"><span>REHEARSAL EVIDENCE EXPLORER</span><a href="../docs/ARCHITECTURE.md">Architecture</a><a href="../reports/reference/README.md">Measured report</a></nav></header>
<main><section class="top"><div><div class="kicker">Customer acceptance / Version 0.1 preview</div><h1>Beyond the happy path.<br>Before the handoff.</h1><p class="lead">A customer-specific evidence contract for agent deployments. Expose missing coverage, preserve failure witnesses, and make approval refer to the exact work that was tested.</p></div><aside class="scope"><b>READ-ONLY • SYNTHETIC CASE STUDY</b><p>This explorer displays actual bundled local results. It does not call a model, execute a workflow or deploy infrastructure. Target policies are scripted; scores are not production reliability estimates.</p></aside></section>
<div class="controls" role="tablist" aria-label="Measured case studies"></div>
<section class="stats"><div class="stat"><div class="label">Handoff gate</div><div class="big status" id="status"></div><div class="detail" id="reason"></div></div><div class="stat"><div class="label">Required-cell coverage</div><div class="big" id="coverage"></div><div class="bar"><div class="fill" id="coverage-bar"></div></div><div class="detail" id="cells"></div></div><div class="stat"><div class="label">Observed witness pass rate</div><div class="big" id="rate"></div><div class="detail">Not a reliability probability</div></div><div class="stat"><div class="label">Observed critical failures</div><div class="big" id="failures"></div><div class="detail" id="casecount"></div></div></section>
<div class="method" id="insight"></div>
<section class="workspace"><article class="panel"><div class="panel-head"><div><h2>Witness-Coverage Matrix</h2><div class="muted" style="font-size:13px">Required obligation × operational slice</div></div><span class="chip">12 REQUIRED CELLS</span></div><table><thead><tr><th>OBLIGATION</th><th>OPERATIONAL SLICE</th><th>OWNER</th><th>STATE</th></tr></thead><tbody id="matrix"></tbody></table><p class="note">A passing normal example cannot cover an ERP outage. Repeated witnesses do not create new coverage.</p></article>
<article class="panel"><div class="panel-head"><div><h2>Counterexample inspection</h2><div class="muted" style="font-size:13px">Expected checks vs observed behavior</div></div></div><select id="case-select" aria-label="Select counterexample"></select><div id="counter"></div><div class="sub"><h3>Evidence binding</h3><div class="label">Exact rehearsal digest</div><p class="digest" id="digest"></p><p class="note">Content hashes detect changes. They are not digital signatures, evaluator attestations or proof of correctness.</p><a id="rawlink" href="#" style="font-size:13px">Open the complete generated dossier →</a></div></article></section>
<section class="panel" style="margin-top:24px"><div class="kicker">Engineering atlas</div><h2 style="margin-top:10px">The mechanism. The boundary. The customer handoff.</h2><div class="atlas"><a href="../assets/01-system-atlas.png">01 / System architecture</a><a href="../assets/02-runtime-statechart.png">02 / Native graph design</a><a href="../assets/03-witness-gate.png">03 / Witness gate</a><a href="../assets/04-aws-reference.png">04 / AWS target</a><a href="../assets/05-azure-reference.png">05 / Azure target</a><a href="../assets/06-trust-boundaries.png">06 / Trust boundaries</a><a href="../assets/07-fde-delivery-loop.png">07 / FDE delivery</a><a href="../assets/08-evidence-model.png">08 / Evidence model</a></div><p class="caption">Cloud topology is reference architecture. Optional LangGraph, live Bedrock, Docker and Terraform validation remain explicitly separate from the tested reference path.</p></section>
<footer class="footer"><span>ASTERION / Independent portfolio prototype / Ashutosh Gandhi</span><span>No customer data. No external writes. No production certification.</span></footer></main>
<script id="cases" type="application/json">__DATA__</script>
<script>
'use strict';const data=JSON.parse(document.getElementById('cases').textContent);let active=0;
const $=id=>document.getElementById(id);const fmt=x=>(x*100).toFixed(x===1?0:1)+'%';
function inspect(){const examples=data[active].assessment.counterexamples;const area=$('counter');area.replaceChildren();if(!examples.length){const e=document.createElement('div');e.className='empty';e.textContent=data[active].assessment.missing_cells.length?'No failing example was observed. That is not evidence that untested situations pass. Missing cells keep this handoff on hold.':'All authored required cells passed in this finite rehearsal. A human reviewer must still accept the exact evidence capsule.';area.append(e);return;}const pre=document.createElement('pre');pre.textContent=JSON.stringify(examples[Number($('case-select').value)],null,2);area.append(pre);}
function render(i){active=i;const s=data[i],a=s.assessment;document.querySelectorAll('.tab').forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-selected',String(i===j));});$('status').textContent=s.status==='PENDING_REVIEW'?'PENDING REVIEW':s.status;$('status').className='big status '+(s.status==='BLOCKED'?'red':s.status==='HOLD'?'amber':'mint');$('reason').textContent=s.status==='BLOCKED'?'Critical acceptance obligations failed':s.status==='HOLD'?'Missing evidence is not a pass':'Complete evidence; human decision required';$('coverage').textContent=fmt(a.coverage);$('coverage-bar').style.width=fmt(a.coverage);$('cells').textContent=a.cells.filter(c=>c.status!=='MISSING').length+' of '+a.cells.length+' required cells observed';$('rate').textContent=fmt(a.observed_pass_rate);$('failures').textContent=a.failed_cells.length;$('failures').className='big '+(a.failed_cells.length?'red':'mint');$('casecount').textContent=s.completed_ids.length+' synthetic cases executed';$('insight').textContent=a.missing_cells.length?'A perfect observed score can hide untested failure modes. This run leaves '+a.missing_cells.length+' required cells without evidence.':a.failed_cells.length?'Complete coverage exposes the real gap: '+a.failed_cells.length+' operational cells fail the customer contract.':'The guarded policy meets the authored synthetic contract. Readiness still means review—not deployment.';const body=$('matrix');body.replaceChildren();a.cells.forEach(c=>{const tr=document.createElement('tr');[c.obligation_id,c.slice,c.owner].forEach(t=>{const td=document.createElement('td');td.textContent=t;tr.append(td)});const td=document.createElement('td'),pill=document.createElement('span');pill.className='pill '+c.status;pill.textContent=c.status;td.append(pill);tr.append(td);body.append(tr)});const sel=$('case-select');sel.replaceChildren();sel.hidden=!a.counterexamples.length;a.counterexamples.forEach((c,j)=>{const o=document.createElement('option');o.value=j;o.textContent=c.scenario_id+' / '+c.obligation_id;sel.append(o)});$('digest').textContent=s.evidence_digest;$('rawlink').href='../reports/reference/'+s.request.profile+'-'+s.request.suite+'/report.html';inspect();}
data.forEach((s,i)=>{const b=document.createElement('button');b.className='tab';b.role='tab';const name=document.createElement('strong');name.textContent=s.request.profile==='guarded'?'Guarded policy':'Optimistic policy';const detail=document.createElement('small');detail.textContent=s.request.suite==='complete'?'Complete operational suite':'Happy-path examples only';b.append(name,detail);b.onclick=()=>render(i);document.querySelector('.controls').append(b)});$('case-select').onchange=inspect;render(0);
</script></body></html>'''
(S/'index.html').write_text(html.replace('__DATA__',data),encoding='utf-8',newline='\n')
(S/'README.md').write_text('# Offline evidence explorer\n\nOpen `index.html` directly in a browser. No server, API key or build step is needed. The embedded data is copied from the four actual synthetic reports under `reports/reference/`. Controls select and inspect those results; they do not execute a live agent. Regenerate with `python scripts/build_site.py` after updating benchmark reports.\n',encoding='utf-8',newline='\n')
